`timescale 1ns/1ps

// V35S core v2: the microcode sequencer (docs/v35s-core-v2.md, "Microcode"; Appendix B §2-§3;
// stage S3). It runs the started form's template from the microcode ROM (v35_ucode.hex as
// four banks v35_ucode_b0..3.hex, generated by validation/v35s/chains/ucgen.py: one row per
// timed model step, the zero-time
// steps folded in as the row's wait `wcond` and side effect `arm`), with the hardwired
// counters and holds the rows do not carry: the resume countdown, the take sync, the unit
// hold's parity, the write-back countdown, the shift / multiply / element loop counts, the
// latch holds. It replaces stage S2's scripted EU (v35_eu_script.sv): the T pass and the P
// pass are S2's, the rows come from the ROM.
//
// The ROM. Four banks (row address mod 4), each a block RAM with one read port whose read is
// registered at `ce` (q0..q3): the clock reads a window of four consecutive rows (`wa` ..
// wa + 3) besides the current row, held in `row_c`. While a form runs the window follows its
// cursor (the rows a pass may reach after the current one); when the current row is the
// template's last, or no form runs, the window holds the first rows of the template the next
// form will run, decoded a clock ahead (`nf_*`: the IR, or the queue's head byte, and its
// ModR/M byte as they stand at this clock's end; v35_loader). A start whose template's first
// row is not in the window waits a clock (W_DEC: the decode was not known a clock ahead; the
// trace counts them).
//
// One pass (S2's T pass, S5's P pass) evaluates at most three rows: a row and the ones its
// completion releases on the same clock (`tdelay` 0, a satisfied wait, a skipped row), or a
// form's end, the start gate and the new form's first rows (S2's lead take and its clocks were
// one row; the ROM has them as two); the P pass takes one operand byte at most. A row is
//   [skip] [ENTRY arm] [wait wcond] [PRE_OP arm] [op] [EXIT arm]
// and passes as the model's steps pass in eu.tick (validation/v35s/chains/sim/eu.py:696-1373):
// CLOCKS loads the resume countdown (a count of 0 passes as ("clocks", 0)), TAKE takes its
// bytes through the loader (LEAD goes on, CHAIN resumes a clock later, a plain or WORD take
// ends with the take sync, PORT with the port latch's relatch), DATA posts and waits for its
// own request, POST / POST_IO post and go on, FLUSH / FLUSH_C / DECIDE wait out the fetch gap,
// HALT stops; NOWAIT counts clocks not in a bus wait state.
//
// Stage map (one registered update at `ce`; everything else feed-forward, no block reads its
// own outputs):
//   S2  T: (A) the resume countdown and unit_hold, the form's end (done, the write-back), the
//       start gate and the first row, (B) the take sync, (C) one row, (D) one row more (or the
//       form's end, the start gate and the next form's first row), (E) a third row
//   S5  P (retick: a detached I/O issued): the same, bounded to the S5 vocabulary (the start
//       gate, one first-row action, one post, an IR load is the loader's)
//   S6  the next state: the cursor, the current row and the window's address (the decode
//       ahead), the countdowns, the latch_start / one_idle / long_exec adjustments
//
// Registered state (widths) and the model variables it replaces:
//   run 1, upc 11, row_c 64, rc_v 1         eu.steps / eu.k (the cursor and its row)
//   base 11                                 the running template's first row (row 0 tests)
//   wa 11, q0..q3 4 x 64                    the ROM window's first row, the banks' read registers
//   arm_done 1, wpass 1                     the cursor row's side effect done, its wait passed
//   res 11                                  eu.resume as a countdown (resume - t, next clock)
//   left 3, taken 3, oplen 3                eu.left, eu.taken, eu.op_len
//   sync_v 1, sync_def 1, owed 2            eu.sync (pending / defer) as fetches still owed
//   held 1                                  _port_take's inserted ("slot",) (the NOHELD skip)
//   own_v 1, dpass 1                        eu.own; a data / wait step passed (_mem_unit_hold)
//   exec_v 1, ex_age 2, ex_par 1, hold_done 1   eu.exec_t (t - exec_t sat, parity), hold_done
//   abort_start 1                           queue.abort_t == eu.start_clock
//   done_m 1, wbu 2, wbc 2, wbx 1           eu.done_t is set; eu.wb_until - t; eu.wb;
//                                           one_idle's eu.wb += 1
//   lu_inf 1, lu 3                          eu.latch_until - t (inf while a detached OUT waits)
//   halted 1, refill 1                      eu.halted, eu.refill
//   nw_v 1, nw 4                            eu.left_nw (NOWAIT)
//   first_clk 1, lx 1                       the counting clocks are row 0's (latch_start,
//                                           one_idle); long_exec's wait-clock count (rot4_from)
//   elem 16, ltop 11                        the element loop (S5's strings and BCD): the
//                                           element index, the body's first row
//   fmt 115, cc 122, op 8                   the running form's format, class constants
//                                           (v35_cls_t) and opcode byte
//   shift_held_r 1                          eu.shift_latched (count_latch)
//   slot_rl 2                               the held detached I/O's class relatch
//   (mt_floor, page_mt*, pf_cnt: the 0F page's timers, S5; named here, not built)
module v35_ucode
    import v35_front_pkg::*;
    import v35_pkg::*;
#(
    // the ROM's bank images (ucgen.py: v35_ucode_b0..3.hex), the directory relative to the
    // simulation's working directory (the repository root)
    parameter string UCODE_DIR = "fpga/v35s/core/v35/"
)
(
    input  wire        clock,
    input  wire        reset_n,
    input  wire        ce,

    // the loader / queue (S1 values; the loader's IR before S2 and after S3)
    input  wire        ir_v_c,
    input  v35_fmt_t   fmt_c,           // the IR's format (its ModR/M byte the head byte)
    input  v35_cls_t   cls_c,           // ... its class constants
    input  v35_cls_t   cls_l,           // the IR's after L
    input  v35_fmt_t   fmt_mt,          // the running form's format re-decoded at a T take of
    input  v35_fmt_t   fmt_mp,          // its ModR/M byte (the loader's), at a P take
    input  wire [7:0]  ir_c,
    input  wire        ir_v_l,
    input  v35_fmt_t   fmt_l,
    input  wire [7:0]  ir_l,
    input  wire [19:0] ir_addr_c,
    input  wire [19:0] ir_addr_l,
    input  wire [7:0]  vb0, vb1, vb2, vb3,
    input  wire [3:0]  avail_c,
    input  wire        l_pop,
    input  wire        arrived_now,
    input  wire        lat_c,
    input  wire        lat_x,
    input  wire        inflight_c,
    input  wire        inflight_x,
    input  wire        completed_now,
    input  wire signed [4:0] room_c,
    input  wire signed [4:0] room_p0,
    input  wire [3:0]  stored_c,
    input  wire [3:0]  stored_l,
    input  wire        rq_old_c,
    input  wire        rq_old_p,
    input  wire        b2b_now,
    input  wire        asked_d,
    input  wire        asked_t,
    input  wire        asked_p,
    input  wire        retry,
    input  wire        retry_loop,
    input  wire        latch_start_now,
    input  wire        shift_latch,     // count_latch: the count byte's take latched (queue)
    input  wire signed [4:0] room_e,    // the room at the clock's end (one_idle)
    // the decode ahead (S6): the next clock's IR (or head byte) and its format
    input  wire        nf_v,
    input  v35_fmt_t   nf_fmt,
    input  wire [19:0] nf_addr,
    // the bus (S0)
    input  wire        bus_free,
    input  wire        busy,
    input  wire [2:0]  cur_kind,
    input  wire [2:0]  cur_left,
    input  wire        cur_on_start,
    input  wire        fetch_inflight,
    input  wire        fetch_past_b2,
    input  wire [3:0]  fetch_since,
    input  wire        in_wait,
    input  wire        abort_busy,
    input  wire        abort_last,
    input  wire        wl_busy,
    input  wire        wl_busy_x,
    input  wire [2:0]  grant_len,
    // the arbiter
    input  wire        slot_wait_c,
    input  wire        slot_wait_p,
    input  wire        slot_det_c,
    input  wire        slot_det_p,
    input  wire        own_issued,
    input  wire        own_done,
    input  wire        g_fetch,
    input  wire        g_abort,
    input  wire        g_abort_lat,     // abort_latched: the aborted cycle the latched byte's
    input  wire        retick,
    input  wire        g_io,
    // the datapath
    input  wire [8:0]  cnt,             // the shift count (CNT rows)
    input  wire [7:0]  cl_c,            // CL now (a shift by CL's cnt0)
    input  wire [7:0]  cl_e,            // CL after this clock (the decode ahead's cnt0)
    input  wire [3:0]  mneg,            // MUL's sign clocks (UNIT rows)
    input  wire [15:0] elems,           // (S5) the element loop's count
    input  wire        str_cond,        // (S5) the compare ended on its condition
    input  wire        bf_cross,        // (S5) the bit field crosses a word
    input  wire [9:0]  bfcost,          // (S5) the bit field's cost

    // S2 outputs
    output wire        t_start,
    output wire [1:0]  t_k,
    output wire        t_done,
    output wire        t_flush,
    output wire        t_halt,
    output wire [2:0]  t_fhold,         // fetch_hold n (arm HOLD): no request for n clocks
    output wire        ask_d,
    output wire        ask_t,
    output wire        cnt_take,        // count_latch: a shift's count byte take ends now
    output wire        rt_set,
    output wire signed [9:0] rt_n,
    output wire        sh_set,          // count_latch: the shift's last clock is t + sh_n
    output wire [9:0]  sh_n,
    output wire        imm16_c,
    output wire        imm16_t,
    output wire        nop_cand,
    output wire        abort_loop,
    output wire        halting,
    output wire        halted_o,
    output wire        wb_hold,
    output wire        latch_wait,
    output wire        relatch,
    output wire        relatch_late,
    output wire [1:0]  relatch_n,
    output wire        retire,
    output wire        lx_hold,         // long_exec: the loader's ready countdown holds a clock
    output wire        idle_adj,        // one_idle: the loader's ready countdown a clock less
    // the posts (S2, S5): the request descriptor (v35_eu builds the address and datum)
    output wire        post_t,
    output uc_row_t    prow_t,
    output wire [6:0]  psetup_t,
    output wire        pfnv_t,          // ... its free_need (none: every setup clock free)
    output wire [2:0]  pfn_t,
    output wire [1:0]  plead_t,         // ... an I/O request's lead
    output wire        post_p,
    output uc_row_t    prow_p,
    output wire [6:0]  psetup_p,
    output wire        pfnv_p,
    output wire [2:0]  pfn_p,
    output wire [1:0]  plead_p,
    // S5 outputs
    output wire        p_start,
    output wire        p_k,
    output wire        p_done,
    output wire        p_io_nx,
    output wire        ask_p,
    output wire        io_drop,         // io_take=unit (the P take)
    output wire        io_drop_loop,
    output wire        imm16_p,
    output wire        wl_fill_t,
    output wire        wl_fill_p,
    output wire        start_any,
    // the next state (the datapath's port schedule)
    output wire        run_e,           // a form runs on the next clock
    output wire        aim_next,        // ... reading no register: the ports serve the next
    output v35_fmt_t   fmt_e,           // its format
    // the trace
    output wire [3:0]  wait_o,
    output wire [10:0] res_o,
    output wire        dec_miss         // a start waited for its decode (W_DEC)
);
    // ------------------------------------------------------------ the ROM: four banks
    localparam int NB = (V35_N_ROWS + 3) / 4;
    logic [V35_ROW_BITS-1:0] bank0 [0:NB - 1];     // (plain vectors: block RAM inference)
    logic [V35_ROW_BITS-1:0] bank1 [0:NB - 1];
    logic [V35_ROW_BITS-1:0] bank2 [0:NB - 1];
    logic [V35_ROW_BITS-1:0] bank3 [0:NB - 1];
    initial begin
        $readmemh({UCODE_DIR, "v35_ucode_b0.hex"}, bank0);
        $readmemh({UCODE_DIR, "v35_ucode_b1.hex"}, bank1);
        $readmemh({UCODE_DIR, "v35_ucode_b2.hex"}, bank2);
        $readmemh({UCODE_DIR, "v35_ucode_b3.hex"}, bank3);
    end

    // ------------------------------------------------------------ registered state
    reg        run = 1'b0;
    reg [10:0] upc = 11'd0;
    uc_row_t   row_c = '0;
    reg        rc_v = 1'b0;
    reg [10:0] base = 11'd0;
    reg [10:0] wa = 11'd0;
    reg        arm_done = 1'b0;
    reg        wpass = 1'b0;
    reg [10:0] res = 11'd0;
    reg [2:0]  left = 3'd0;
    reg [2:0]  taken = 3'd0;
    reg [2:0]  oplen = 3'd1;
    reg        sync_v = 1'b0;
    reg        sync_def = 1'b0;
    reg [1:0]  owed = 2'd0;
    reg        held = 1'b0;
    reg        own_v = 1'b0;
    reg        dpass = 1'b0;
    reg        exec_v = 1'b0;
    reg [1:0]  ex_age = 2'd0;
    reg        ex_par = 1'b0;
    reg        hold_done = 1'b0;
    reg        abort_start = 1'b0;
    reg        done_m = 1'b1;
    reg [1:0]  wbu = 2'd0;
    reg [1:0]  wbc = 2'd0;
    reg        lu_inf = 1'b0;
    reg [2:0]  lu = 3'd0;
    reg        halted = 1'b0;
    reg        refill = 1'b0;
    reg        nw_v = 1'b0;
    reg [3:0]  nw = 4'd0;
    reg        first_clk = 1'b0;
    reg        lx = 1'b0;
    reg [15:0] elem = 16'd0;
    reg [10:0] ltop = 11'd0;
    v35_fmt_t  fmt = '0;
    v35_cls_t  cc = '0;                 // the running form's class constants
    reg [7:0]  op = 8'h00;
    reg        shift_held_r = 1'b0;     // count_latch: the queue's shift_held (from the latch)
    reg        wbx = 1'b0;              // one_idle: a write-back clock more at the form's end
    reg [1:0]  slot_rl = 2'd0;          // the waiting detached I/O's class's relatch

    // the window: rows wa .. wa + 3 (bank (wa + j) mod 4 at its registered address)
    uc_row_t   q0 = '0, q1 = '0, q2 = '0, q3 = '0;    // the banks' read registers
    function automatic uc_row_t wrow(input logic [1:0] j);
        logic [1:0] b;
        b = wa[1:0] + j;
        case (b)
            2'd0: wrow = q0;
            2'd1: wrow = q1;
            2'd2: wrow = q2;
            default: wrow = q3;
        endcase
    endfunction

    // the row at address a: the current row, or one of the window's (v: it is there)
    typedef struct packed {
        logic    v;
        uc_row_t r;
    } rv_t;
    function automatic rv_t rowat(input logic [10:0] a);
        logic [10:0] d;
        d = a - wa;
        rowat.v = 1'b1;
        if (run && rc_v && a == upc)
            rowat.r = row_c;
        else if (d < 11'd4)
            rowat.r = wrow(d[1:0]);
        else begin
            rowat.r = '0;
            rowat.v = 1'b0;
        end
    endfunction

    // wait reasons (the trace's W)
    localparam logic [3:0] W_NONE = 4'd0, W_CLK = 4'd1, W_HOLD = 4'd2, W_SYNC = 4'd3,
                           W_BYTES = 4'd4, W_LATE = 4'd5, W_LATCH = 4'd6, W_DATA = 4'd7,
                           W_ISSUED = 4'd8, W_SLOT = 4'd9, W_WBSYNC = 4'd10, W_GATE = 4'd11,
                           W_IR = 4'd12, W_HALT = 4'd13, W_FLUSH = 4'd14, W_IOEXEC = 4'd15;
    localparam logic [3:0] W_DEC = W_GATE;   // (shares the gate's code; dec_miss tells them apart)

    // ------------------------------------------------------------ one pass (T or P)
    typedef struct packed {
        logic        run;
        logic [10:0] a;
        logic [10:0] base;
        logic        arm_done;
        logic        wpass;
        logic [10:0] res;       // resume - t on this clock
        logic [2:0]  left;
        logic [2:0]  taken;
        logic [2:0]  oplen;
        logic        sync_v;
        logic        sync_def;
        logic        held;
        logic        own_v;
        logic        dpass;
        logic        exec_v;
        logic        halted;
        logic        done_m;
        logic        started;   // a form started in this pass
        logic        stc;       // ... on this clock (T or P: eu.start_clock == t)
        logic [1:0]  wbc;
        logic        nw_v;
        logic [3:0]  nw;
        logic        first_clk;
        logic        lx;
        logic [15:0] elem;
        logic [10:0] ltop;
        v35_fmt_t    fmt;
        v35_cls_t    cc;
        logic [7:0]  op;
    } ps_t;

    typedef struct packed {
        logic        is_p;
        logic [3:0]  avail;     // bytes the decoder may take now
        logic [7:0]  b0;        // the head byte now (a ModR/M take's re-decode)
        logic        ir_v;      // the IR holds an opcode (before this pass's start)
        logic        late;      // a fetch past its second clock (late_read)
        logic        lu_busy;   // t < latch_until
        logic [2:0]  lu_val;    // latch_until - t
        logic        wbu_busy;  // t < wb_until
        logic        slot_wait; // a request waits unissued in the slot
        logic        slot_det;  // ... a detached I/O write
        logic        cur_io_s;  // an I/O cycle that started on the form's start clock runs
        logic [2:0]  cur_left;
        logic        cur_io_now;    // an I/O cycle issued on this clock (P)
        logic        lat;       // latched before this pass's take (imm_landed, port_landed)
        logic        own_done;
        logic        own_issued;
        logic        retry_ok;  // q.retry and q.retry_loop
        logic        abort_st;
        logic        finfl;     // a fetch on the bus (flush, quiet)
        v35_fmt_t    fm;        // the running form re-decoded with this pass's ModR/M byte
        v35_fmt_t    fs;        // ... a form started in this pass (its start's decode)
    } env_t;

    typedef struct packed {
        logic        complete;
        logic        cont;
        logic [3:0]  why;       // the wait reason when not complete
        logic [1:0]  tk;        // bytes taken
        logic        tk_done;   // the take step committed
        logic        ask;       // a take's queue.asked(t) (the request flag evaluated)
        logic        syn;       // ... and its take sync kept (owed from asked(t) unless def)
        logic        def;       // imm_landed: the sync deferred
        logic        cntk;      // a shift's count byte taken (count_latch's candidate)
        logic        post;      // the row's request posts
        logic        relatch;
        logic        landed;    // port_landed
        logic        wl_fill;
        logic        rt_set;
        logic signed [9:0] rt_n;
        logic        sh_set;
        logic [9:0]  sh_n;
        logic [2:0]  fhold;
        logic        flush;
        logic        halt;
        logic        io_nx;
        logic        iodrop;    // io_take=unit: the take's request dropped (eu._io_drop)
        logic        set_exec;
        logic        retire;
        logic        rom_miss;  // the next row was not in the window
        uc_row_t     row;       // the row that acted (its request)
        logic [6:0]  setup;     // its request's setup
        logic        fnv;       // ... its free_need
        logic [2:0]  fn;
        logic [1:0]  lead;      // ... an I/O request's lead
    } fx_t;

    /* verilator lint_off UNUSEDSIGNAL */
    // the row's count (CLOCKS, NOWAIT) or its request's setup (nsrc + imm)
    function automatic logic [10:0] nval(input uc_row_t r, input ps_t s);
        logic [10:0] k;
        v35_cls_t c;
        c = s.cc;
        case (r.nsrc)
            V35_NSRC_EA: nval = 11'(r.imm) + 11'(v35_ea_clocks(s.fmt.ea_mode));
            V35_NSRC_CNT: nval = 11'(r.imm) + 11'(V35_PER_SHIFT_COUNT) * {2'd0, cnt};
            V35_NSRC_UNIT: nval = 11'(r.imm) + {7'd0, mneg};
            V35_NSRC_BF: nval = {1'b0, bfcost} > 11'(r.imm) ? {1'b0, bfcost} - 11'(r.imm)
                                                             : 11'd0;
            V35_NSRC_STR: begin
                k = s.elem == 16'd0 ? 11'(c.first) : (s.elem == 16'd1 ? 11'(c.loop1)
                                                                       : 11'(c.loop));
                nval = 11'(r.imm) + k;
            end
            default: nval = 11'(r.imm);
        endcase
    endfunction

    // the row is skipped (a skipped row passes in no time)
    function automatic logic skipped(input uc_row_t r, input ps_t s);
        case (r.skip)
            V35_SKIP_COND: skipped = str_cond;
            V35_SKIP_NCOND: skipped = !str_cond;
            V35_SKIP_NOHELD: skipped = !s.held;
            V35_SKIP_CROSS: skipped = bf_cross;
            V35_SKIP_NCROSS: skipped = !bf_cross;
            default: skipped = 1'b0;
        endcase
    endfunction

    // the row's side effect (arm): its outputs
    function automatic void do_arm(input uc_row_t r, inout fx_t x);
        case (r.arm)
            V35_ARM_HOLD: x.fhold = r.x[2:0];   // fetch_hold n (POP PSW's 2); (the other arms:
            default: ;                          //  the strings', the bit fields', S5)
        endcase
    endfunction

    // leaving a row: the next one (the element loop's top after its last body row)
    function automatic void adv(inout ps_t s, input uc_row_t r);
        logic more;
        more = r.loop && (s.elem + 16'd1 < elems);
        if (r.ltop)
            s.ltop = s.a;
        if (r.loop)
            s.elem = s.elem + 16'd1;
        s.a = more ? s.ltop : s.a + 11'd1;
        s.arm_done = 1'b0;
        s.wpass = 1'b0;
        if (r.last && !more) begin
            s.run = 1'b0;
            s.wbc = r.wb;
        end
    endfunction

    // One row r (the cursor's) at the pass state s: its entry, or its continuation on a later
    // clock.
    function automatic void do_row(inout ps_t s, input env_t e, input uc_row_t r,
                                   input rv_t rn, output fx_t x);
        logic [10:0] n;
        logic [2:0] left0, cap, kk, need;
        logic dnext, unit_e;
        v35_cls_t c;
        v35_fmt_t fm;
        c = s.cc;
        n = nval(r, s);
        x = '0;
        x.row = r;
        x.setup = 7'(n + ((r.lastadd && s.elem + 16'd1 >= elems && !str_cond) ? 11'(c.last)
                                                                                : 11'd0));
        // free_need: the row's (x, or setup - x), else the class's setup_free (None without);
        // an I/O request's lead
        case (r.i2m)
            V35_I2M_LIT: begin x.fnv = 1'b1; x.fn = r.x[2:0]; end
            V35_I2M_SETUP_MINUS: begin x.fnv = 1'b1; x.fn = 3'(x.setup - r.x); end
            default: begin x.fnv = c.setup_free_v; x.fn = c.setup_free; end
        endcase
        x.lead = (r.rkind == V35_RK_IO_READ || r.rkind == V35_RK_IO_WRITE) ? c.lead : 2'd0;
        need = s.oplen - 3'd1 - s.taken;
        // a skipped row
        if (skipped(r, s)) begin
            x.complete = 1'b1;
            x.cont = 1'b1;
            adv(s, r);
            return;
        end
        // the side effect before the wait
        if (r.arm != V35_ARM_NONE && r.apos == V35_APOS_ENTRY && !s.arm_done) begin
            do_arm(r, x);
            s.arm_done = 1'b1;
        end
        // the wait
        if (!s.wpass) begin
            case (r.wcond)
                V35_WC_OWN_DONE: if (s.own_v) begin
                    if (!e.own_done) begin
                        x.why = W_DATA;
                        return;
                    end
                    s.own_v = 1'b0;
                    s.dpass = 1'b1;
                    x.retire = 1'b1;
                end
                V35_WC_OWN_ISSUED: if (s.own_v && !e.own_issued) begin
                    x.why = W_ISSUED;
                    return;
                end
                V35_WC_SLOT: begin
                    if (e.slot_wait) begin
                        x.why = W_SLOT;
                        return;
                    end
                    if (e.lu_busy && e.lu_val != 3'd0) begin
                        s.wpass = 1'b1;         // resume = max(t, latch_until)
                        s.res = 11'(e.lu_val);
                        x.why = W_SLOT;
                        return;
                    end
                end
                V35_WC_WB: if (e.wbu_busy) begin
                    x.why = W_WBSYNC;
                    return;
                end
                V35_WC_QUIET: if (e.finfl) begin     // (S5: and no fetch wanted)
                    x.why = W_FLUSH;
                    return;
                end
                default: ;
            endcase
        end
        s.wpass = 1'b1;
        // the side effect after the wait
        if (r.arm != V35_ARM_NONE && r.apos == V35_APOS_PRE_OP && !s.arm_done) begin
            do_arm(r, x);
            s.arm_done = 1'b1;
        end
        case (r.op)
            V35_OP_CLOCKS: begin
                if (n == 11'd0) begin
                    x.complete = 1'b1;          // ("clocks", 0): no clock
                    x.cont = 1'b1;
                end else if (s.taken != 3'd0 && !s.fmt.mem && need == 3'd0
                             && s.fmt.interlock && e.cur_io_s) begin
                    // io_exec=after_io: a register form started on an I/O cycle's issue clock
                    // runs its clocks after its operand take only once the cycle has ended
                    x.why = W_IOEXEC;
                    s.wpass = 1'b0;
                    s.res = 11'(e.cur_left);
                    return;
                end else begin
                    x.complete = 1'b1;
                    s.res = n;
                    // unit_hold: the exec's first clock (a register shift / MUL / DIV with its
                    // operand bytes taken; a memory MUL imm after its read, mul_imm_exec=hold)
                    unit_e = (s.fmt.unit_reg && !s.fmt.mem)
                             || (s.fmt.mem && s.fmt.mul_imm && s.dpass);
                    if (!s.exec_v && unit_e && s.taken != 3'd0 && need == 3'd0) begin
                        s.exec_v = 1'b1;
                        x.set_exec = 1'b1;
                    end
                    s.first_clk = s.a == s.base;
                    // long_exec=wait: a long one-byte form's clocks do not count a fetch's
                    // wait clock (the IR load moves with them)
                    s.lx = s.fmt.long1 && s.a == s.base && s.oplen == 3'd1;
                    if (r.last && e.retry_ok && e.abort_st && s.fmt.unit_reg) begin
                        // abort_unit=loop: a register shift started on an aborted cycle raises
                        // the dropped request as its last count iteration starts; a register
                        // multiply / divide mtail clocks before its end (io_take, abort_reg)
                        x.rt_set = 1'b1;
                        x.rt_n = $signed({1'b0, 9'(n)})
                                 - (s.fmt.xop == V35_XOP_SHIFT ? 10'sd2 : 10'(c.mtail));
                    end
                    if (r.last && shift_held_r) begin
                        x.sh_set = 1'b1;        // count_latch: the shift's last clock
                        x.sh_n = 10'(n) - 10'd1;
                    end
                end
            end
            V35_OP_NOWAIT: begin
                if (!s.nw_v) begin
                    s.nw_v = 1'b1;
                    s.nw = 4'(n);               // (lookup_start: S4)
                end
                if (s.nw != 4'd0 && !in_wait)
                    s.nw = s.nw - 4'd1;
                if (s.nw != 4'd0) begin
                    s.wpass = 1'b0;
                    s.res = 11'd1;
                    x.why = W_CLK;
                end else begin
                    s.nw_v = 1'b0;
                    x.complete = 1'b1;
                    x.cont = 1'b1;
                end
            end
            V35_OP_TAKE: begin
                left0 = s.left != 3'd0 ? s.left : r.aidx;
                cap = (r.tag == V35_TAG_WORD || r.tag == V35_TAG_CHAIN_WORD) ? 3'd2 : 3'd1;
                kk = left0 < cap ? left0 : cap;
                if ({1'b0, kk} > e.avail)
                    kk = 3'(e.avail);
                s.left = left0;
                s.wpass = 1'b0;                 // (a take that waits re-checks nothing)
                if (e.lu_busy && s.fmt.immb != 2'd0
                    && s.taken >= s.oplen - 3'd1 - 3'(s.fmt.immb))
                    x.why = W_LATCH;            // imm_latch=wait: an OUT's I/O holds the latch
                // decoder.loads_after(t, 1): the IR would load on t too after this last byte
                else if (e.late && left0 == 3'd1 && !(e.ir_v && !s.started) && need == 3'd1
                         && c.nx == 3'd0 && !s.halted && e.avail > 4'd1)
                    x.why = W_LATE;             // late_read: the take and the IR load wait
                else if (kk == 3'd0)
                    x.why = W_BYTES;
                else begin
                    x.tk = 2'(kk);
                    if (s.taken == 3'd0 && s.fmt.has_modrm) begin
                        // the ModR/M byte: the form's format as it decodes (the start decoded
                        // the head byte)
                        fm = s.started ? e.fs : e.fm;
                        s.fmt.md = fm.md;
                        s.fmt.rfield = fm.rfield;
                        s.fmt.rm = fm.rm;
                        s.fmt.disp = fm.disp;
                        s.fmt.ea_mode = fm.ea_mode;
                        s.fmt.bix16 = fm.bix16;
                        s.oplen = fm.len;
                    end
                    s.taken = s.taken + kk;
                    s.left = left0 - kk;
                    need = s.oplen - 3'd1 - s.taken;
                    // wlatch_src=write_imm_read: the last immediate byte of a form without a
                    // memory operand; wlatch_imm=reg_last: the last operand byte of any
                    // register-only form: into the data latch on its take
                    x.wl_fill = need == 3'd0 && !s.fmt.mem
                                && (s.fmt.immb != 2'd0 || s.fmt.interlock);
                    // io_take_nx: a register form's last operand byte taken on an I/O cycle's
                    // issue clock: its IR load a clock later
                    x.io_nx = e.is_p && e.cur_io_now && need == 3'd0 && s.fmt.breg;
                    // io_take=unit: a register-only form started on an I/O cycle's issue clock
                    // took its last operand byte there, on a word's delivery clock with the
                    // word's second byte latched: the fetch request it raises is dropped, raised
                    // again as an aborted cycle's (at a count loop's exit)
                    x.iodrop = e.is_p && e.cur_io_now && s.stc && need == 3'd0 && !s.fmt.mem
                               && s.fmt.interlock && arrived_now && e.lat && s.left == 3'd0;
                    if (s.left != 3'd0) begin
                        x.why = W_BYTES;
                    end else begin
                        x.tk_done = 1'b1;
                        x.complete = 1'b1;
                        // count_latch's candidate: a take of a register shift by an immediate
                        // count ends (the queue decides the latch)
                        x.cntk = s.fmt.xop == V35_XOP_SHIFT && s.fmt.unit_reg
                                 && s.fmt.immb != 2'd0;
                        // post_on_take=nomodrm: the next timed step a data request, in a form
                        // without a ModR/M byte: posted on the take clock
                        dnext = rn.v && rn.r.op == V35_OP_DATA && rn.r.wcond == V35_WC_NONE
                                && !(rn.r.arm != V35_ARM_NONE && rn.r.apos != V35_APOS_EXIT)
                                && !s.fmt.modrm_op;
                        if (r.tag == V35_TAG_PORT) begin
                            x.relatch = 1'b1;
                            x.landed = arrived_now && e.lat && e.avail > 4'(kk);
                            if (e.slot_det)
                                s.held = 1'b1;  // ("slot",), (post_io, ...) inserted
                            else
                                x.post = 1'b1;  // the I/O posted on the take clock
                            s.res = 11'd1;
                        end else if (r.tag == V35_TAG_LEAD) begin
                            x.cont = 1'b1;      // alongside the next step's clocks
                        end else if (r.tag == V35_TAG_CHAIN || r.tag == V35_TAG_CHAIN_WORD) begin
                            s.res = 11'd1;      // more operand bytes follow: no sync
                        end else if (dnext) begin
                            x.cont = 1'b1;      // post the request on the take clock
                        end else begin
                            // take_sync=pending: the fetches in flight or asked for now;
                            // imm_landed defers it a clock; sync_req=disp: none after a
                            // memory immediate form's displacement
                            x.def = s.fmt.immb != 2'd0 && !s.fmt.mem && arrived_now && e.lat
                                    && e.avail > 4'(kk);
                            x.ask = 1'b1;       // queue.asked(t): the flag evaluated
                            x.syn = !(s.fmt.immb != 2'd0 && s.fmt.mem && s.fmt.disp != 2'd0);
                            if (x.syn) begin
                                s.sync_v = 1'b1;
                                s.sync_def = x.def;
                            end
                            s.res = 11'd1;
                        end
                        adv(s, r);
                    end
                end
            end
            V35_OP_DATA: begin
                if (!s.own_v) begin
                    if (e.slot_wait) begin
                        x.why = W_SLOT;         // S2/S3: nothing queues behind a request
                    end else begin
                        x.post = 1'b1;
                        s.own_v = 1'b1;
                        x.why = W_DATA;
                    end
                end else if (e.own_done) begin
                    x.complete = 1'b1;
                    x.cont = 1'b1;
                    s.own_v = 1'b0;
                    s.dpass = 1'b1;
                    x.retire = 1'b1;
                end else begin
                    x.why = W_DATA;
                end
            end
            V35_OP_POST, V35_OP_POST_IO: begin
                if (e.slot_wait) begin
                    x.why = W_SLOT;
                end else begin
                    x.post = 1'b1;
                    if (r.op == V35_OP_POST)
                        s.own_v = 1'b1;
                    x.complete = 1'b1;
                    x.cont = 1'b1;
                end
            end
            V35_OP_FLUSH, V35_OP_FLUSH_C, V35_OP_DECIDE: begin
                if (e.finfl || fetch_since <= (r.op == V35_OP_FLUSH ? c.fgap
                                               : r.op == V35_OP_FLUSH_C ? c.cfgap
                                               : {3'd0, c.nfgap})) begin
                    x.why = W_FLUSH;
                end else begin
                    x.flush = r.op != V35_OP_DECIDE;
                    x.complete = 1'b1;
                    x.cont = 1'b1;
                end
            end
            V35_OP_HALT: begin
                x.halt = 1'b1;
                x.why = W_HALT;
                s.halted = 1'b1;
                adv(s, r);
                s.run = 1'b0;
            end
            default: begin                      // NOP; (S5) FROM_START, SPLIT_FLOOR: no clock
                x.complete = 1'b1;
                x.cont = 1'b1;
            end
        endcase
        if (x.complete && r.op != V35_OP_TAKE) begin
            if (r.arm != V35_ARM_NONE && r.apos == V35_APOS_EXIT)
                do_arm(r, x);
            adv(s, r);
        end else if (x.complete && r.arm != V35_ARM_NONE && r.apos == V35_APOS_EXIT) begin
            do_arm(r, x);
        end
    endfunction

    // the start gate (eu._start under the fit, in format bits); `wl` the data latch
    function automatic logic gate(input v35_fmt_t f, input logic ir_v, input logic is_p,
                                  input logic slot_det, input logic rq_old, input logic infl,
                                  input logic [3:0] stored, input logic wl, input logic rfb);
        logic ok;
        ok = ir_v && !rfb;              // refill_start=full_io: a flush's refill first
        if (!is_p && fetch_inflight)
            ok = 1'b0;                  // start_sync: no start with a fetch on the bus
        if (f.modrm_op && b2b_now && !(f.page != 2'd0 && !f.mem))
            ok = 1'b0;                  // start_sync=b2b_modrm (page_start=reg)
        if (f.regonly && slot_det)
            ok = 1'b0;                  // io_interlock=reg_pfx: an OUT's I/O waits in the slot
        if (f.regonly && busy && cur_kind == K_IO_WRITE)
            ok = 1'b0;                  // io_busy_start=issue: not after the OUT's issue clock
        if (f.port_io && wl)
            ok = 1'b0;                  // wlatch, wlatch_cls=port
        if ((f.port_io || f.modrm_op) && rq_old && !infl && !is_p && bus_free
            && stored < 4'(V35_IO_B2B_Q))
            ok = 1'b0;                  // io_older=io_modrm (the bus is never free in P)
        if (!f.modrm_op && b2b_now && stored < 4'(V35_IO_B2B_Q))
            ok = 1'b0;                  // io_b2b=all
        return ok;
    endfunction

    // the template a form starts: its first row (the start-time bits: cnt0 from CL, half from
    // the last operand byte's address; taken / zfail: the transfers, S5)
    function automatic logic [10:0] tbase(input v35_fmt_t f, input logic [19:0] a,
                                          input logic [7:0] cl);
        v35_run_t rb;
        logic [19:0] last;
        rb = '0;
        rb.cnt0 = cl == 8'd0;
        last = a + 20'(f.len) - 20'd1;
        rb.half = !last[0];
        tbase = v35_tmpl_base(v35_tmpl_of(f, rb));
    endfunction

    // a form starts: the pass state for its first row
    function automatic void start_ps(inout ps_t s, input v35_fmt_t f, input v35_cls_t c,
                                     input logic [7:0] o, input logic [10:0] b);
        s.run = 1'b1;
        s.a = b;
        s.base = b;
        s.arm_done = 1'b0;
        s.wpass = 1'b0;
        s.res = 11'd0;
        s.left = 3'd0;
        s.taken = 3'd0;
        s.oplen = f.len;
        s.held = 1'b0;
        s.own_v = 1'b0;
        s.dpass = 1'b0;
        s.exec_v = 1'b0;
        s.done_m = 1'b0;
        s.started = 1'b1;
        s.stc = 1'b1;
        s.nw_v = 1'b0;
        s.first_clk = 1'b0;
        s.lx = 1'b0;
        s.elem = 16'd0;
        s.ltop = b;
        s.fmt = f;
        s.cc = c;
        s.op = o;
    endfunction
    /* verilator lint_on UNUSEDSIGNAL */

    // ------------------------------------------------------------ S2: the T pass
    wire        lu_busy_c = lu_inf || lu != 3'd0;
    wire [1:0]  owed_c = owed - (completed_now && owed != 2'd0 ? 2'd1 : 2'd0);
    wire [1:0]  hphase = cc.hphase;

    // the template of the IR's form if it starts now (T: the IR; P: the IR after L)
    wire [10:0] base_c = tbase(fmt_c, ir_addr_c, cl_c);
    wire [10:0] base_l = tbase(fmt_l, ir_addr_l, cl_c);

    ps_t   s0, s1, s2, s3, s4;
    fx_t   x1, x2, x3;
    env_t  et;
    rv_t   g1, g2, r1, r1n, r2, r2n, r3, r3n;
    logic  t_hold, t_wait, t_sync_blk, t_gate1, t_gate2, t_try1, t_try2, t_dec1, t_dec2;
    logic  t_lapse, t_done_rec, t_ev1, t_ev2, t_ev3, t_end2, t_areg;
    logic [3:0] t_why;
    logic [1:0] owed_t;
    logic [10:0] hold_res;
    logic [1:0] wbu_t1, wbu_t2;

    always_comb begin
        s0 = '0;
        s0.run = run;
        s0.a = upc;
        s0.base = base;
        s0.arm_done = arm_done;
        s0.wpass = wpass;
        s0.res = res;
        s0.left = left;
        s0.taken = taken;
        s0.oplen = oplen;
        s0.sync_v = sync_v;
        s0.sync_def = sync_def;
        s0.held = held;
        s0.own_v = own_v;
        s0.dpass = dpass;
        s0.exec_v = exec_v;
        s0.halted = halted;
        s0.done_m = done_m;
        s0.wbc = wbc;
        s0.nw_v = nw_v;
        s0.nw = nw;
        s0.first_clk = first_clk;
        s0.lx = lx;
        s0.elem = elem;
        s0.ltop = ltop;
        s0.fmt = fmt;
        s0.cc = cc;
        s0.op = op;

        et = '0;
        et.avail = avail_c;
        et.b0 = vb0;
        et.ir_v = ir_v_c;
        et.late = fetch_past_b2;
        et.lu_busy = lu_busy_c;
        et.lu_val = lu;
        et.slot_wait = slot_wait_c;
        et.slot_det = slot_det_c;
        et.cur_io_s = cur_on_start && k_io(cur_kind);
        et.cur_left = cur_left;
        et.lat = lat_c;
        et.own_done = own_done;
        et.own_issued = own_issued;
        et.retry_ok = retry && retry_loop;
        et.abort_st = abort_start;
        et.finfl = fetch_inflight;
        et.fm = fmt_mt;
        et.fs = fmt_c;

        // (A) the clocks wait; unit_hold: the exec clocks wait at a micro-boundary (every
        // second clock from hphase; a memory form's on any clock) while a fetch is past its
        // second clock (or an aborted cycle ends), to that cycle's end; once per cycle
        t_hold = !halted && exec_v && res != 11'd0 && !hold_done
                 && (fmt.mem || (ex_age >= hphase && ex_par == hphase[0]))
                 && (fetch_past_b2 || abort_last);
        hold_res = res + (fetch_past_b2 ? 11'(cur_left) : 11'd1);
        t_wait = halted || res != 11'd0;

        // the form's end (eu.done_t), then the start (before the take sync: eu.tick's order)
        s1 = s0;
        t_done_rec = !t_wait && !run && !done_m;
        if (t_done_rec)
            s1.done_m = 1'b1;
        wbu_t1 = t_done_rec ? wbc + (wbx ? 2'd1 : 2'd0) : wbu;
        et.wbu_busy = wbu_t1 != 2'd0;
        t_gate1 = gate(fmt_c, ir_v_c, 1'b0, slot_det_c, rq_old_c, inflight_c, stored_c,
                       wl_busy, refill && (inflight_c || room_c >= 5'sd2));
        t_try1 = !t_wait && !run && !halted;
        g1 = rowat(base_c);
        t_dec1 = t_try1 && t_gate1 && !g1.v;
        if (t_try1 && t_gate1 && g1.v)
            start_ps(s1, fmt_c, cls_c, ir_c, base_c);

        // (B) the take sync (once a form runs): owed fetches not delivered, unless the
        // request lapsed
        t_lapse = !inflight_c && !abort_busy && room_c < 5'sd2;
        owed_t = sync_def ? (inflight_c ? 2'd1 : 2'd0) + (asked_d ? 2'd1 : 2'd0) : owed_c;
        // abort_reg: a register shift by a count byte or 1, multiply or divide started on an
        // aborted cycle runs its exec from that cycle's last clock (the one fetch it owed)
        t_areg = abort_last && abort_start && !fmt.mem && fmt.unit_reg
                 && !(fmt.xop == V35_XOP_SHIFT && fmt.opb == V35_ROLE_CL) && owed_t == 2'd1;
        t_sync_blk = !t_wait && s1.run && sync_v && owed_t != 2'd0 && !t_lapse && !t_areg;
        if (!t_wait && s1.run && sync_v)
            s1.sync_def = 1'b0;         // a deferred sync is counted now (met or not)
        if (!t_wait && s1.run && !t_sync_blk)
            s1.sync_v = 1'b0;

        // (C) the cursor's row
        t_ev1 = !t_wait && !t_sync_blk && !s1.halted && s1.run;
        r1 = rowat(s1.a);
        r1n = rowat(s1.a + 11'd1);
        s2 = s1;
        x1 = '0;
        if (t_ev1 && r1.v)
            do_row(s2, et, r1.r, r1n, x1);
        x1.rom_miss = t_ev1 && !r1.v;

        // (D) a second row when the first one completed with `cont`
        et.avail = avail_c - 4'(x1.tk);
        et.b0 = x1.tk == 2'd0 ? vb0 : (x1.tk == 2'd1 ? vb1 : vb2);
        s3 = s2;
        x2 = '0;
        t_end2 = t_ev1 && x1.complete && x1.cont && !s2.run && !s1.started;
        if (t_end2)
            s3.done_m = 1'b1;
        wbu_t2 = t_end2 ? s2.wbc + (wbx ? 2'd1 : 2'd0) : wbu_t1;
        et.wbu_busy = wbu_t2 != 2'd0;
        t_gate2 = gate(fmt_c, ir_v_c && !x1.flush, 1'b0, slot_det_c, rq_old_c, inflight_c,
                       stored_c, wl_busy, (refill || x1.flush) && (inflight_c || room_c >= 5'sd2
                                                                   || x1.flush));
        t_try2 = t_end2 && !s2.halted;
        g2 = rowat(base_c);
        t_dec2 = t_try2 && t_gate2 && !g2.v;
        if (t_try2 && t_gate2 && g2.v)
            start_ps(s3, fmt_c, cls_c, ir_c, base_c);
        t_ev2 = t_ev1 && x1.complete && x1.cont && (s2.run || (t_try2 && t_gate2 && g2.v));
        r2 = rowat(s3.a);
        r2n = rowat(s3.a + 11'd1);
        if (t_ev2 && r2.v)
            do_row(s3, et, r2.r, r2n, x2);
        x2.rom_miss = t_ev2 && !r2.v;

        // (E) a third row after a form's end and start: the row a LEAD take releases (S2
        // folded the lead take into its clocks row)
        et.avail = avail_c - 4'(x1.tk) - 4'(x2.tk);
        et.b0 = (x1.tk + x2.tk) == 2'd0 ? vb0 : ((x1.tk + x2.tk) == 2'd1 ? vb1 : vb2);
        s4 = s3;
        x3 = '0;
        t_ev3 = t_ev2 && x2.complete && x2.cont && s3.run && s3.started;
        r3 = rowat(s3.a);
        r3n = rowat(s3.a + 11'd1);
        if (t_ev3 && r3.v)
            do_row(s4, et, r3.r, r3n, x3);
        x3.rom_miss = t_ev3 && !r3.v;

        t_why = halted ? W_HALT : t_hold ? W_HOLD : t_wait ? W_CLK : t_sync_blk ? W_SYNC :
                (t_dec1 || t_dec2) ? W_DEC :
                ((t_try1 && !t_gate1) || (t_try2 && !t_gate2)) ? (ir_v_c ? W_GATE : W_IR) :
                t_ev3 ? x3.why : t_ev2 ? x2.why : t_ev1 ? x1.why : W_NONE;
    end

    assign t_start = s1.started || s3.started;
    fx_t xt;
    always_comb begin
        xt = x1 | x2 | x3;
        xt.rt_n = x1.rt_set ? x1.rt_n : (x2.rt_set ? x2.rt_n : x3.rt_n);
        xt.sh_n = x1.sh_set ? x1.sh_n : (x2.sh_set ? x2.sh_n : x3.sh_n);
        xt.fhold = x1.fhold != 3'd0 ? x1.fhold : (x2.fhold != 3'd0 ? x2.fhold : x3.fhold);
        xt.row = x3.post ? x3.row : (x2.post ? x2.row : x1.row);
        xt.setup = x3.post ? x3.setup : (x2.post ? x2.setup : x1.setup);
        xt.fnv = x3.post ? x3.fnv : (x2.post ? x2.fnv : x1.fnv);
        xt.fn = x3.post ? x3.fn : (x2.post ? x2.fn : x1.fn);
        xt.lead = x3.post ? x3.lead : (x2.post ? x2.lead : x1.lead);
    end
    assign t_k = xt.tk;
    assign t_done = xt.tk_done;
    assign t_flush = xt.flush;
    assign t_halt = xt.halt;
    assign t_fhold = xt.fhold;
    assign ask_d = !t_wait && s1.run && sync_v && sync_def;
    assign ask_t = xt.ask;
    assign cnt_take = xt.cntk;
    assign rt_set = xt.rt_set;
    assign rt_n = xt.rt_n;
    assign sh_set = xt.sh_set;
    assign sh_n = xt.sh_n;
    assign halting = xt.halt;
    assign halted_o = halted;
    // abort_unit=loop: a count-loop form started on this clock (a register shift, a register
    // multiply / divide (abort_reg), a memory multiply / divide)
    assign abort_loop = t_start && (s3.fmt.unit_reg
                                    || (s3.fmt.unit_mem && (s3.fmt.xop == V35_XOP_MUL
                                                            || s3.fmt.xop == V35_XOP_DIV
                                                            || s3.fmt.xop == V35_XOP_MULI)));
    // nop_hold: a register-only form without operand bytes started on this clock
    assign nop_cand = t_start && s3.fmt.one_reg;
    // wb_fetch=hold: the form started on this clock waits at its first row's write-back wait
    rv_t r0t;
    always_comb r0t = rowat(s4.base);
    assign wb_hold = t_start && s4.a == s4.base && r0t.v && r0t.r.wcond == V35_WC_WB
                     && wbu_t2 != 2'd0;
    // wlatch_hold: an I/O form waits at its start for the data latch (the checks before
    // eu._start's wlatch test passed)
    assign latch_wait = (t_try1 || t_try2) && ir_v_c && !fetch_inflight && !refill
                        && fmt_c.port_io && wl_busy;
    assign retire = xt.retire;
    // eu.cls / imm_bytes as the room's room_ir_imm reads them: the running (or last) form
    assign imm16_c = fmt.imm16_reg;
    assign imm16_t = s4.fmt.imm16_reg;

    // ------------------------------------------------------------ S5: the P pass
    // machine.py's retick on a detached I/O's issue clock: the start gate again (the I/O
    // interlock satisfied), the started form's first row, a SLOT wait's release
    ps_t   p0, p1, p2, p3, p4;
    fx_t   y1, y2, y3;
    env_t  ep;
    rv_t   h1, h2, u1, u1n, u2, u2n, u3, u3n;
    logic  p_gate1, p_gate2, p_try1, p_try2, p_ev1, p_ev2, p_wait, p_sync_blk, p_lapse;
    logic  p_done_rec, p_end2, p_dec1, p_dec2, p_ev3;
    logic [1:0] wbu_p1, wbu_p2;

    always_comb begin
        p0 = s4;
        p0.started = 1'b0;
        ep = et;
        ep.is_p = 1'b1;
        ep.avail = avail_c - 4'(xt.tk) - (l_pop ? 4'd1 : 4'd0);
        ep.b0 = xt.tk == 2'd0 ? (l_pop ? vb1 : vb0) : (xt.tk == 2'd1 ? (l_pop ? vb2 : vb1)
                                                                  : (l_pop ? vb3 : vb2));
        ep.ir_v = ir_v_l;
        ep.late = 1'b0;                 // the bus holds the I/O just issued
        ep.lu_busy = 1'b1;              // ... and it holds the latches to its end
        ep.lu_val = grant_len;
        ep.slot_wait = slot_wait_p;
        ep.slot_det = slot_det_p;
        ep.cur_io_s = g_io;             // the cycle issued now, on a P start's clock
        ep.cur_left = grant_len;
        ep.cur_io_now = g_io;
        ep.lat = lat_x;
        ep.own_done = 1'b0;
        ep.own_issued = own_issued;
        ep.finfl = 1'b1;
        ep.fm = fmt_mp;
        ep.fs = fmt_l;

        p_wait = !retick || p0.halted || p0.res != 11'd0;
        p1 = p0;
        p_done_rec = !p_wait && !p0.run && !p0.done_m;
        if (p_done_rec)
            p1.done_m = 1'b1;
        wbu_p1 = p_done_rec ? p0.wbc + (wbx ? 2'd1 : 2'd0) : wbu_t2;
        ep.wbu_busy = wbu_p1 != 2'd0;
        p_gate1 = gate(fmt_l, ir_v_l, 1'b1, slot_det_p, rq_old_p, inflight_x, stored_l,
                       wl_busy_x, refill);
        p_try1 = !p_wait && !p0.run;
        h1 = rowat(base_l);
        p_dec1 = p_try1 && p_gate1 && !h1.v;
        if (p_try1 && p_gate1 && h1.v)
            start_ps(p1, fmt_l, cls_l, ir_l, base_l);
        p_lapse = !inflight_x && !abort_busy && room_p0 < 5'sd2;
        p_sync_blk = !p_wait && p1.run && p1.sync_v && !p_lapse;
        if (!p_wait && p1.run && !p_sync_blk)
            p1.sync_v = 1'b0;
        p_ev1 = !p_wait && !p_sync_blk && p1.run;
        u1 = rowat(p1.a);
        u1n = rowat(p1.a + 11'd1);
        p2 = p1;
        y1 = '0;
        if (p_ev1 && u1.v)
            do_row(p2, ep, u1.r, u1n, y1);
        y1.rom_miss = p_ev1 && !u1.v;
        p3 = p2;
        y2 = '0;
        p_end2 = p_ev1 && y1.complete && y1.cont && !p2.run && !p1.started;
        if (p_end2)
            p3.done_m = 1'b1;
        wbu_p2 = p_end2 ? p2.wbc + (wbx ? 2'd1 : 2'd0) : wbu_p1;
        ep.wbu_busy = wbu_p2 != 2'd0;
        p_gate2 = gate(fmt_l, ir_v_l, 1'b1, slot_det_p, rq_old_p, inflight_x, stored_l,
                       wl_busy_x, refill);
        p_try2 = p_end2;
        h2 = rowat(base_l);
        p_dec2 = p_try2 && p_gate2 && !h2.v;
        if (p_try2 && p_gate2 && h2.v)
            start_ps(p3, fmt_l, cls_l, ir_l, base_l);
        if (y1.tk != 2'd0)
            ep.avail = 4'd0;            // (P: one byte at most)
        p_ev2 = p_ev1 && y1.complete && y1.cont
                && (p2.run || (p_try2 && p_gate2 && h2.v));
        u2 = rowat(p3.a);
        u2n = rowat(p3.a + 11'd1);
        if (p_ev2 && u2.v)
            do_row(p3, ep, u2.r, u2n, y2);
        y2.rom_miss = p_ev2 && !u2.v;
        p4 = p3;
        y3 = '0;
        if (y2.tk != 2'd0)
            ep.avail = 4'd0;
        p_ev3 = p_ev2 && y2.complete && y2.cont && p3.run
                && p3.started;
        u3 = rowat(p3.a);
        u3n = rowat(p3.a + 11'd1);
        if (p_ev3 && u3.v)
            do_row(p4, ep, u3.r, u3n, y3);
        y3.rom_miss = p_ev3 && !u3.v;
    end

    assign p_start = p1.started || p3.started;
    fx_t xp;
    always_comb begin
        xp = y1 | y2 | y3;
        xp.rt_n = y1.rt_set ? y1.rt_n : (y2.rt_set ? y2.rt_n : y3.rt_n);
        xp.sh_n = y1.sh_set ? y1.sh_n : (y2.sh_set ? y2.sh_n : y3.sh_n);
        xp.fhold = y1.fhold != 3'd0 ? y1.fhold : (y2.fhold != 3'd0 ? y2.fhold : y3.fhold);
        xp.row = y3.post ? y3.row : (y2.post ? y2.row : y1.row);
        xp.setup = y3.post ? y3.setup : (y2.post ? y2.setup : y1.setup);
        xp.fnv = y3.post ? y3.fnv : (y2.post ? y2.fnv : y1.fnv);
        xp.fn = y3.post ? y3.fn : (y2.post ? y2.fn : y1.fn);
        xp.lead = y3.post ? y3.lead : (y2.post ? y2.lead : y1.lead);
    end
    assign p_k = xp.tk != 2'd0;
    assign p_done = xp.tk_done;
    assign p_io_nx = xp.io_nx;
    assign ask_p = xp.ask && !xp.iodrop;
    assign io_drop = xp.iodrop;
    assign io_drop_loop = p4.fmt.unit_reg;
    assign imm16_p = p4.fmt.imm16_reg;
    assign wl_fill_t = xt.wl_fill;
    assign wl_fill_p = xp.wl_fill;
    assign start_any = t_start || p_start;
    assign dec_miss = t_dec1 || t_dec2 || p_dec1 || p_dec2;

    // ------------------------------------------------------------ the posts
    assign post_t = xt.post;
    assign prow_t = xt.row;
    assign psetup_t = xt.setup;
    assign pfnv_t = xt.fnv;
    assign pfn_t = xt.fn;
    assign plead_t = xt.lead;
    assign post_p = xp.post && !xt.post;
    assign prow_p = xp.row;
    assign psetup_p = xp.setup;
    assign pfnv_p = xp.fnv;
    assign pfn_p = xp.fn;
    assign plead_p = xp.lead;
    // port_latch=relatch: the slot's waiting I/O (its poster's class's relatch), port_landed
    assign relatch = xt.relatch;
    assign relatch_late = xt.landed;
    assign relatch_n = slot_rl;

    // ------------------------------------------------------------ S6: the next state
    // latch_start: the byte latched behind a full queue went in on the clock a form whose
    // first step is a clocks step started (and is in it): its clocks begin a clock later
    wire       st_now = t_start || p_start;
    rv_t       r0p;
    always_comb r0p = rowat(p4.base);
    wire       r0c = st_now && p4.first_clk && p4.res != 11'd0 && p4.a == p4.base + 11'd1;
    wire       r0_plain = r0p.v && r0p.r.wcond == V35_WC_NONE
                          && !(r0p.r.arm != V35_ARM_NONE && r0p.r.apos == V35_APOS_ENTRY);
    wire       ls_adj = latch_start_now && r0c && r0_plain;
    // one_idle=long: a one-byte form of the set started with the queue full and no bus cycle
    // on its start clock runs a clock less (its IR load too); its last clock becomes a
    // write-back unless it is a long form
    wire       oi_adj = r0c && r0_plain && p4.fmt.idle1 && !g_fetch && !retick && !g_abort
                        && !busy && room_e < 5'sd2;
    assign idle_adj = oi_adj;
    // long_exec=wait: a fetch's wait clock does not count (the IR load moves with it)
    wire       lx_now = p4.lx && p4.res != 11'd0 && busy && cur_kind == K_FETCH && in_wait;
    assign lx_hold = lx_now;
    // count_latch: the count byte taken on the latched delivery clock reaches the shift
    // counter a clock later; the take sync waits for the fetches in flight only
    wire        cl_hold = xt.cntk && xt.syn && (shift_latch || shift_held_r);
    wire [10:0] res_e = t_hold ? hold_res
                      : (p4.res + (ls_adj ? 11'd1 : 11'd0) - (oi_adj ? 11'd1 : 11'd0)
                         + (lx_now ? 11'd1 : 11'd0)
                         + ((cl_hold && arrived_now) ? 11'd1 : 11'd0));
    // the take sync's count: in flight + asked on the take clock (a held detached I/O's
    // request not counted; sync_io=issue: nor one asked under the I/O's issue clock)
    wire [1:0]  owed_tk = (inflight_c ? 2'd1 : 2'd0)
                          + (asked_t && !slot_det_c && !cl_hold ? 2'd1 : 2'd0);
    wire [1:0]  owed_pk = (inflight_x ? 2'd1 : 2'd0)
                          + (asked_p && !slot_det_p && !g_io ? 2'd1 : 2'd0);
    wire        end_any = t_done_rec || t_end2 || p_done_rec || p_end2;
    // the fetches the take sync still owes after this clock; abort_latched: a sync that counted
    // no request waits for the aborted cycle the latched byte answered
    wire [1:0]  owed_s = (xp.syn && !xp.def) ? owed_pk
                       : (xt.syn && (!xt.def || cl_hold)) ? owed_tk
                       : ask_d ? owed_t : owed_c;
    wire [1:0]  owed_n = (g_abort_lat && p4.sync_v && !p4.sync_def && owed_s == 2'd0) ? 2'd1
                                                                                        : owed_s;
    wire [1:0]  wb_end = p_end2 ? p2.wbc : (p_done_rec ? p0.wbc : (t_end2 ? s2.wbc : wbc));
    wire [2:0]  wb_tot = {1'b0, wb_end} + (wbx ? 3'd1 : 3'd0);

    // the next cursor's row, the window's address (the decode ahead when no row follows)
    rv_t        nrow;
    always_comb nrow = rowat(p4.a);
    wire        loop_e = p4.run && nrow.v && nrow.r.loop && p4.elem + 16'd1 < elems;
    wire        ahead_e = !p4.run || (nrow.v && nrow.r.last && nrow.r.skip == V35_SKIP_NONE
                                      && !loop_e);
    wire [10:0] base_e = tbase(nf_fmt, nf_addr, cl_e);
    wire [10:0] wa_e = loop_e ? p4.ltop
                     : ahead_e ? (nf_v ? base_e : wa)
                     : (nrow.v ? p4.a + 11'd1 : p4.a);
    /* verilator lint_off UNUSEDSIGNAL */
    function automatic logic [8:0] bank_a(input logic [10:0] w, input logic [1:0] b);
        logic [10:0] x;
        x = w + 11'(2'(b - w[1:0]));
        bank_a = x[10:2];
    endfunction
    /* verilator lint_on UNUSEDSIGNAL */

    assign run_e = p4.run;
    assign fmt_e = p4.fmt;
    // the next clock evaluates no row of the running form that reads its registers (its last
    // row, a request it has posted waiting, or no form): the register ports may serve the
    // next form (the decode ahead)
    assign aim_next = ahead_e && !(p4.run && nrow.v && !p4.own_v
                                   && (nrow.r.op == V35_OP_DATA || nrow.r.op == V35_OP_POST
                                       || nrow.r.op == V35_OP_POST_IO));
    assign wait_o = t_why;
    assign res_o = res;

    always_ff @(posedge clock) begin
        if (ce) begin
            q0 <= uc_row_t'(bank0[bank_a(wa_e, 2'd0)]);
            q1 <= uc_row_t'(bank1[bank_a(wa_e, 2'd1)]);
            q2 <= uc_row_t'(bank2[bank_a(wa_e, 2'd2)]);
            q3 <= uc_row_t'(bank3[bank_a(wa_e, 2'd3)]);
        end
    end

    always_ff @(posedge clock) begin
        if (!reset_n) begin
            run <= 1'b0;
            upc <= 11'd0;
            row_c <= '0;
            rc_v <= 1'b0;
            base <= 11'd0;
            wa <= 11'd0;
            arm_done <= 1'b0;
            wpass <= 1'b0;
            res <= 11'd0;
            left <= 3'd0;
            taken <= 3'd0;
            oplen <= 3'd1;
            sync_v <= 1'b0;
            sync_def <= 1'b0;
            owed <= 2'd0;
            held <= 1'b0;
            own_v <= 1'b0;
            dpass <= 1'b0;
            exec_v <= 1'b0;
            ex_age <= 2'd0;
            ex_par <= 1'b0;
            hold_done <= 1'b0;
            abort_start <= 1'b0;
            done_m <= 1'b1;
            wbu <= 2'd0;
            wbc <= 2'd0;
            lu_inf <= 1'b0;
            lu <= 3'd0;
            halted <= 1'b0;
            refill <= 1'b0;
            nw_v <= 1'b0;
            nw <= 4'd0;
            first_clk <= 1'b0;
            lx <= 1'b0;
            elem <= 16'd0;
            ltop <= 11'd0;
            fmt <= '0;
            cc <= '0;
            op <= 8'h00;
            shift_held_r <= 1'b0;
            wbx <= 1'b0;
            slot_rl <= 2'd0;
        end else if (ce) begin
            run <= p4.run;
            upc <= p4.a;
            row_c <= nrow.r;
            rc_v <= nrow.v;
            base <= p4.base;
            wa <= wa_e;
            arm_done <= p4.arm_done;
            wpass <= p4.wpass;
            res <= res_e == 11'd0 ? 11'd0 : res_e - 11'd1;
            left <= p4.left;
            taken <= p4.taken;
            oplen <= p4.oplen;
            sync_v <= p4.sync_v;
            sync_def <= p4.sync_def && !cl_hold;
            owed <= owed_n;
            held <= p4.held;
            own_v <= p4.own_v;
            dpass <= p4.dpass;
            exec_v <= p4.exec_v;
            if (xt.set_exec || xp.set_exec) begin
                ex_age <= 2'd1;
                ex_par <= 1'b1;
            end else begin
                if (ex_age != 2'd3)
                    ex_age <= ex_age + 2'd1;
                ex_par <= !ex_par;
            end
            if (t_hold)
                hold_done <= 1'b1;
            else if (g_fetch || g_abort)
                hold_done <= 1'b0;
            if (st_now)
                abort_start <= (t_start && g_abort) || xp.iodrop;
            done_m <= p4.done_m;
            wbc <= p4.wbc;
            fmt <= p4.fmt;
            cc <= p4.cc;
            op <= p4.op;
            halted <= p4.halted;
            if (xt.flush)
                refill <= 1'b1;
            else if (st_now)
                refill <= 1'b0;
            // eu.wb_until - t, from the clock a form's steps end (wb_from=end)
            if (end_any)
                wbu <= wb_tot == 3'd0 ? 2'd0 : 2'(wb_tot - 3'd1);
            else if (wbu != 2'd0)
                wbu <= wbu - 2'd1;
            if (st_now)
                wbx <= oi_adj && !p4.fmt.long1;
            else if (end_any)
                wbx <= 1'b0;
            // the latches an OUT's detached I/O holds (eu.latch_until): from its post to the
            // end of its cycle
            if (retick && g_io) begin
                lu_inf <= 1'b0;
                lu <= grant_len - 3'd1;         // latch_until = end + 1
            end else begin
                if ((post_t && prow_t.rkind == V35_RK_IO_WRITE && prow_t.detached)
                    || (post_p && prow_p.rkind == V35_RK_IO_WRITE && prow_p.detached))
                    lu_inf <= 1'b1;
                if (lu != 3'd0)
                    lu <= lu - 3'd1;
            end
            if ((post_t && prow_t.detached) || (post_p && prow_p.detached))
                slot_rl <= p4.cc.relatch;
            nw_v <= p4.nw_v;
            nw <= p4.nw;
            first_clk <= p4.first_clk && p4.res != 11'd0;
            lx <= p4.lx && res_e > 11'd1;
            elem <= p4.elem;
            ltop <= p4.ltop;
            // count_latch: held from the count byte's take to the shift's last clock
            if (shift_latch)
                shift_held_r <= 1'b1;
            else if (st_now)
                shift_held_r <= 1'b0;
        end
    end

`ifndef SYNTHESIS
    // +v35_dbg=FILE: the sequencer's state per clock (bring-up only)
    integer dbg = 0;
    reg [31:0] dbg_t = 32'd0;
    string dbg_name;
    initial if ($value$plusargs("v35_dbg=%s", dbg_name)) dbg = $fopen(dbg_name, "w");
    always @(posedge clock) begin
        if (ce && reset_n) begin
            dbg_t <= dbg_t + 32'd1;
            if (dbg != 0)
                $fdisplay(dbg, "uc %0d run%0d upc%0d rc%0d wa%0d res%0d | r1 %0d.%0d op%0d c%0d k%0d m%0d | r2 %0d op%0d c%0d m%0d | st%0d%0d try%0d%0d gate%0d%0d dec%0d%0d base%0d nf%0d->%0d",
                         dbg_t, run, upc, rc_v, wa, res, t_ev1, r1.v, r1.r.op, x1.complete,
                         x1.cont, x1.rom_miss, t_ev2, r2.r.op, x2.complete, x2.rom_miss,
                         s1.started, s3.started, t_try1, t_try2, t_gate1, t_gate2, t_dec1,
                         t_dec2, base_c, nf_v, wa_e);
        end
    end
`endif

    wire unused = &{1'b0, xt.why, xp.why, xt.def, xp.def, xt.complete, xp.complete, xt.cont,
                    xp.cont, xp.relatch, xp.flush, xp.halt, xp.fhold, xp.rt_set, xp.rt_n,
                    xp.retire, xp.set_exec, xp.sh_set, xp.sh_n, xp.cntk, xp.landed, t_lapse,
                    x1.rom_miss, x2.rom_miss, y1.rom_miss, y2.rom_miss, xt, xp, ir_addr_c,
                    room_p0, r1n, r2n, u1n, u2n, cur_left, dpass, nf_addr, g1, g2, h1, h2,
                    ep, et, p4, x3, y3, r3n, u3n};
endmodule
